class Siswa {
    private String nama;
    private int umur;

    String getNama() {
        return nama;
    }

    void setNama(String nama) {
        this.nama = nama;
    }

    int getUmur() {
        return umur;
    }

    void setUmur(int umur) {
        if (umur > 0) {
            this.umur = umur;
        }
    }
}

